// Same-origin Node.js API. Session cookie is HttpOnly; passwords never enter localStorage or app state.
let nodeReady=false,nodeChecked=false,nodeUser=null,nodeCsrf='',nodeNeedsSetup=false,nodeRevision=0,nodeSaving=false,nodeWriteBlocked=false,nodeSaveTimer=null,nodeSaveChain=Promise.resolve();
const nativeEntry=entryView,nativeRegisterFields=registrationFields,nativeRender=render,nativeSave=save,nativeExit=leaveWorkspace;
function passwordInput(name,label,autocomplete='current-password'){return `<label>${label}<div class="password-input"><input name="${name}" type="password" required dir="ltr" autocomplete="${autocomplete}" ${autocomplete==='new-password'?'minlength="10" maxlength="128"':''}><button type="button" data-reveal="${name}" aria-label="إظهار كلمة المرور" aria-pressed="false">إظهار</button></div></label>`}
function validatePassword(password,confirm){if(password.length<10||password.length>128||!/[\p{L}]/u.test(password)||!/[0-9٠-٩]/.test(password))throw Error('كلمة المرور من ١٠ إلى ١٢٨ حرف، وتحتوي على حروف وأرقام.');if(password!==confirm)throw Error('تأكيد كلمة المرور غير مطابق.')}
registrationFields=function(){return nativeRegisterFields().replace('<div class="entry-flow-hint">',`<div class="entry-field-row">${passwordInput('password','كلمة المرور','new-password')}${passwordInput('passwordConfirm','تأكيد كلمة المرور','new-password')}</div><small class="password-help">١٠ أحرف على الأقل، حروف وأرقام. كلمة المرور لا تظهر للمدير.</small><div class="entry-flow-hint">`).replace('إرسال طلب تسجيل موظف للمعاينة','إنشاء الحساب وإرسال طلب الانضمام').replace('إرسال طلب تسجيل موظف','إنشاء الحساب وإرسال طلب الانضمام')};
loginFields=function(){if(entryTab==='setup')return `<form id="entryLogin" class="entry-form">${field('اسم المدير','name')}${field('بريد الإدارة المحدد في إعدادات السيرفر','email','email')}${options('الفرع الرئيسي','branch',db.branches.map(b=>b.name))}${passwordInput('setupToken','رمز إعداد الإدارة من إعدادات السيرفر','off')}${passwordInput('password','كلمة مرور المدير','new-password')}${passwordInput('passwordConfirm','تأكيد كلمة المرور','new-password')}<button class="primary entry-submit">تهيئة الإدارة للمرة الأولى</button></form>`;return `<form id="entryLogin" class="entry-form"><label>البريد الإلكتروني<input name="email" required type="email" autocomplete="username" dir="ltr" value="${esc(entryEmail)}" placeholder="name@example.com"></label>${passwordInput('password','كلمة المرور')}<button class="primary entry-submit">تسجيل الدخول ←</button><p class="entry-footnote">حساب جديد؟ التسجيل يحتاج موافقة الإدارة الأولى.</p><button type="button" id="backRegister" class="entry-text-button">تسجيل موظف جديد</button></form>`};
async function nodeApi(path,{method='GET',body}={}){if(!nodeReady)throw Error('قاعدة بيانات التطبيق غير متصلة حاليًا. تقدر تستكشف التصميم فقط، بدون تسجيل كلمة مرور.');const response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(method!=='GET'?{'X-CSRF-Token':nodeCsrf}:{})},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('تعذر الاتصال بسيرفر التطبيق.')}if(!response.ok){if(data.error==='CONFLICT')nodeWriteBlocked=true;throw Object.assign(Error(data.message||'تعذر إتمام العملية'),{code:data.error})}if(data.csrf)nodeCsrf=data.csrf;return data}
function attachPasswordReveals(){document.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{const input=b.closest('label').querySelector('input'),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'إخفاء':'إظهار';b.setAttribute('aria-pressed',String(show))})}
entryView=function(){nativeEntry();const badge=$('.entry-preview-badge');if(badge)badge.textContent='ENERGY PLUS • STAFF';const hint=$('.entry-local-note');if(hint)hint.textContent=nodeReady?'الدخول وبيانات الفريق محفوظان على سيرفر التطبيق. كلمة المرور لا تُحفظ في المتصفح.':'نسخة العرض: خانات كلمة المرور جاهزة، والتسجيل الفعلي يتفعّل بعد توصيل قاعدة بيانات التطبيق.';$('#entryAdmin').textContent='دخول الإدارة ↗';$('#entryAdmin').onclick=()=>{entryTab='login';entryMessage='الإدارة تدخل ببريدها وكلمة المرور.';entryView()};const demo=document.createElement('button');demo.id='demoWorkspace';demo.type='button';demo.className='demo-workspace-link';demo.textContent='استكشاف نسخة العرض ببيانات تجريبية';demo.onclick=()=>enterWorkspace({kind:'admin'});if(!nodeReady)$('.entry-panel-main').append(demo);if(nodeReady&&nodeNeedsSetup){const setup=document.createElement('button');setup.className='server-setup-link';setup.type='button';setup.textContent='تهيئة حساب الإدارة للمرة الأولى';setup.onclick=()=>{entryTab='setup';entryMessage='التهيئة تتطلب رمز إعداد الإدارة من Hostinger؛ لا يوجد باسورد افتراضي.';entryView()};$('.entry-panel-main').append(setup)}attachPasswordReveals();if($('#entryRegister'))$('#entryRegister').onsubmit=async e=>{e.preventDefault();const form=e.target;form.querySelector('.entry-submit').disabled=true;try{const f=new FormData(form);validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));await nodeApi('register',{method:'POST',body:{name:f.get('name'),email:f.get('email'),phone:f.get('phone'),position:f.get('position'),branch:f.get('branch'),password:f.get('password')}});entryEmail=String(f.get('email')).trim();entryMessage='تم استقبال طلب التسجيل. انتظر موافقة الإدارة الأولى ثم سجل دخولك.';entryTab='login';form.reset()}catch(err){entryMessage=err.message}finally{form.querySelectorAll('input[type="password"]').forEach(i=>i.value='');entryView()}};if($('#entryLogin'))$('#entryLogin').onsubmit=async e=>{e.preventDefault();const form=e.target;form.querySelector('.entry-submit').disabled=true;try{const f=new FormData(form);if(entryTab==='setup'){validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));await nodeApi('bootstrap',{method:'POST',body:{name:f.get('name'),email:f.get('email'),branch:f.get('branch'),setupToken:f.get('setupToken'),password:f.get('password')}});nodeNeedsSetup=false;entryTab='login';entryEmail=String(f.get('email')).trim();entryMessage='تم إعداد الإدارة. سجل دخولك بكلمة المرور التي اخترتها.';entryView()}else{const data=await nodeApi('login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});nodeUser=data.user;await enterServerWorkspace()}}catch(err){entryMessage=err.message;entryView()}finally{form.querySelectorAll('input[type="password"]').forEach(i=>i.value='')}}};
async function enterServerWorkspace(){const data=await nodeApi('workspace');db=data.db;nodeRevision=data.revision;nodeWriteBlocked=false;previewSession={kind:nodeUser.role==='employee'?'employee':'admin',employeeId:Number(nodeUser.id)};selectedEmployee=Number(nodeUser.id);role=nodeUser.role==='admin'?'الإدارة':nodeUser.role==='manager'?'مدير قسم':'الموظف';managerDepartment=positions[nodeUser.position];page=nodeUser.role==='admin'?'join-approvals':nodeUser.role==='manager'?'daily-team':'overview';entryRoot.hidden=true;render();if(nodeUser.role==='admin')await refreshServerMembers()}
async function refreshServerData(){if(nodeSaving)return toast('انتظر انتهاء الحفظ');if(nodeWriteBlocked&&!confirm('في تعديلات غير محفوظة بسبب تعارض. تحميل أحدث بيانات السيرفر؟'))return;const data=await nodeApi('workspace');db=data.db;nodeRevision=data.revision;nodeWriteBlocked=false;render()}
function syncStatus(){const el=$('#serverSyncStatus');if(el)el.textContent=nodeWriteBlocked?'تعارض في التحديث — يلزم تحميل الأحدث':nodeSaving?'جارٍ الحفظ على السيرفر…':'متصل بسيرفر الفريق'}
save=function(){if(!nodeUser)return nativeSave();if(nodeUser.role!=='admin')return;clearTimeout(nodeSaveTimer);nodeSaving=true;syncStatus();nodeSaveTimer=setTimeout(()=>{nodeSaveChain=nodeSaveChain.then(async()=>{if(nodeWriteBlocked)throw Error('حدّث البيانات من السيرفر أولًا قبل حفظ تغييرات جديدة.');const snapshot=structuredClone(db);const result=await nodeApi('workspace',{method:'PUT',body:{db:snapshot,revision:nodeRevision}});nodeRevision=result.revision}).catch(e=>{nodeWriteBlocked=true;toast(e.message)}).finally(()=>{nodeSaving=false;syncStatus()})},350)};
async function nativeAction(action,data={}){if(!nodeUser)throw Error('يلزم تسجيل الدخول');const result=await nodeApi('workspace/action',{method:'POST',body:{action,data}});db=result.db;nodeRevision=result.revision;render();return result}
let serverMembers=[];
async function refreshServerMembers(){if(nodeUser?.role!=='admin')return;const data=await nodeApi('members');serverMembers=data.members;if(page==='join-approvals')render()}
function serverApprovals(){return card('طلبات وحسابات الفريق — على السيرفر',`<div class="toolbar"><button id="refreshMembers">تحديث الطلبات</button></div>${serverMembers.filter(m=>m.role!=='admin').map(m=>`<div class="request"><div class="details"><strong>${esc(m.full_name)}</strong><p>${esc(m.email)} • ${esc(m.phone)}<br>${esc(m.requested_position)} — ${esc(m.requested_branch)}</p></div><span class="badge">${({pending:'منتظر الموافقة',approved:'مقبول',rejected:'مرفوض',disabled:'موقوف'})[m.status]}</span><button data-native-review="${m.id}">${m.status==='pending'?'مراجعة':'إدارة الحساب'}</button></div>`).join('')||'<p class="empty">لا توجد طلبات تسجيل جديدة.</p>'}`)}
function reviewServerAccount(id){const m=serverMembers.find(m=>m.id===id);safeSubmit('مراجعة '+m.full_name,options('الحالة','status',['قبول الحساب','رفض الطلب','إيقاف الحساب'])+options('الوظيفة المعتمدة','position',Object.keys(positions))+options('نوع الأكسس','role',['موظف','مدير قسم'])+options('الفرع','branch',db.branches.length?db.branches.map(b=>b.name):[m.requested_branch])+field('ملاحظة القرار','reason'),async f=>{await nodeApi('members/'+id+'/review',{method:'POST',body:{status:({'قبول الحساب':'approved','رفض الطلب':'rejected','إيقاف الحساب':'disabled'})[f.get('status')],position:f.get('position'),branch:f.get('branch'),role:f.get('role')==='مدير قسم'?'manager':'employee',reason:f.get('reason')}});await refreshServerMembers();await refreshServerData()});$('#fields select[name="position"]').value=m.position||m.requested_position}
const localAssign=createAssignment,localChange=changeTask,localCoach=recordCoaching,localLead=createLead,localBreakStart=startBreak,localBreakEnd=endBreak,localPunch=punch,localLeadUpdate=leadUpdateForm,localRequest=requestForEmployee;
createAssignment=function(data){if(!nodeUser||nodeUser.role==='admin')return localAssign(data);return nativeAction('task_assign',data)};
changeTask=function(id,action,note=''){if(!nodeUser||nodeUser.role==='admin')return localChange(id,action,note);return nativeAction(action==='submit'?'task_submit':'task_review',{id,note,approved:action==='approve'})};
recordCoaching=function(data){if(!nodeUser||nodeUser.role==='admin')return localCoach(data);return nativeAction('coach_create',data)};
createLead=function(data){if(!nodeUser||nodeUser.role==='admin')return localLead(data);return nativeAction('sales_create',data)};
startBreak=function(id,source='employee',reason=''){if(!nodeUser||nodeUser.role==='admin')return localBreakStart(id,source,reason);return nativeAction('break_start')};
endBreak=function(id,source='employee',reason=''){if(!nodeUser||nodeUser.role==='admin')return localBreakEnd(id,source,reason);return nativeAction('break_end')};
punch=function(){if(!nodeUser)return localPunch();if(geoBusy)return;const out=!!activePunch(Number(nodeUser.id));if(out&&activeBreak(Number(nodeUser.id)))return toast('أنهِ البريك أولًا');if(!navigator.geolocation)return toast('المتصفح لا يدعم الموقع');geoBusy=true;render();navigator.geolocation.getCurrentPosition(async p=>{try{if(Date.now()-p.timestamp>30000)throw Error('قراءة الموقع قديمة؛ أعد المحاولة');await nativeAction(out?'punch_out':'punch_in',{coords:{latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}});toast('تم التسجيل بعد التحقق من موقع الفرع')}catch(e){toast(e.message)}finally{geoBusy=false;render()}},()=>{geoBusy=false;render();toast('تعذر الوصول للموقع. اسمح بالموقع الدقيق وحاول تاني.')},{enableHighAccuracy:true,maximumAge:0,timeout:20000})};
leadUpdateForm=function(id){if(!nodeUser||nodeUser.role==='admin')return localLeadUpdate(id);const l=db.salesLeads.find(l=>l.id===id);if(!l)return;safeSubmit('متابعة '+l.name,options('المرحلة','stage',leadStages)+options('نتيجة المكالمة','outcome',callOutcomes)+field('الخطوة الجاية','nextAction','text',l.nextAction||'')+'<label>موعد المتابعة بتوقيت القاهرة<input name="followUp" type="datetime-local"></label><label>تفاصيل المكالمة<textarea name="comment" required maxlength="2000"></textarea></label>',async f=>nativeAction('sales_followup',{id,stage:f.get('stage'),outcome:f.get('outcome'),nextAction:f.get('nextAction'),nextFollowUp:f.get('followUp')?cairoToISO(f.get('followUp')):'',comment:f.get('comment')}))};
requestForEmployee=function(){if(!nodeUser)return localRequest();safeSubmit('طلب جديد',options('نوع الطلب','type',['إجازة اعتيادية','إجازة مرضية','إذن انصراف مبكر','تصحيح بصمة','تبديل وردية'])+field('التفاصيل','detail'),async f=>nativeAction('request_create',{type:f.get('type'),detail:f.get('detail')}))};
leaveWorkspace=async function(){if(nodeUser&&nodeSaving){toast('انتظر اكتمال حفظ البيانات قبل الخروج.');return}if(nodeUser){try{await nodeApi('logout',{method:'POST'})}catch(e){toast('تعذر تسجيل الخروج من السيرفر؛ حاول تاني.');return}}nodeUser=null;nodeRevision=0;nodeWriteBlocked=false;serverMembers=[];$('#role').disabled=false;nativeExit();await checkHostingerServer()};
render=function(){if(nodeUser){role=nodeUser.role==='admin'?'الإدارة':nodeUser.role==='manager'?'مدير قسم':'الموظف';selectedEmployee=Number(nodeUser.id);if(nodeUser.role==='manager')managerDepartment=positions[nodeUser.position]}nativeRender();if(!nodeUser||!previewSession)return;$('#role').hidden=true;$('#role').disabled=true;for(const name of ['managerDept','finalManagerDept'])if($('#'+name))$('#'+name).disabled=true;$('.demo').textContent='دخول بكلمة مرور';if(!$('#serverSyncStatus')){$('#app').insertAdjacentHTML('afterbegin','<div class="notice"><span id="serverSyncStatus"></span><button id="reloadServer">تحديث البيانات</button></div>');$('#reloadServer').onclick=()=>refreshServerData().catch(e=>toast(e.message))}syncStatus();if(page==='join-approvals'&&nodeUser.role==='admin'){$('#app').innerHTML=serverApprovals();$('#refreshMembers').onclick=()=>refreshServerMembers().catch(e=>toast(e.message));document.querySelectorAll('[data-native-review]').forEach(b=>b.onclick=()=>reviewServerAccount(Number(b.dataset.nativeReview)))}};
async function checkHostingerServer(){try{const response=await fetch('/api/health',{credentials:'same-origin',cache:'no-store'}),health=await response.json();nodeReady=!!health.ready;if(nodeReady){const s=await nodeApi('session');nodeCsrf=s.csrf;nodeNeedsSetup=s.needsSetup;if(s.user?.status==='approved'){nodeUser=s.user;await enterServerWorkspace();return}}}catch{nodeReady=false}finally{nodeChecked=true}if(!previewSession)entryView()}
setInterval(async()=>{if(!nodeUser)return;try{const s=await nodeApi('session');if(!s.user||s.user.status!=='approved'){nodeUser=null;previewSession=null;entryMessage='الجلسة انتهت أو الحساب موقوف. سجل دخولك من جديد.';entryView()}}catch{}},60000);
render();checkHostingerServer();

$('#closeModal').onclick=()=>$('#modal').close();

function changeAccountPassword(){
 if(!nodeUser)return;
 safeSubmit('تغيير كلمة المرور',
  passwordInput('currentPassword','كلمة المرور الحالية')+
  passwordInput('password','كلمة المرور الجديدة','new-password')+
  passwordInput('passwordConfirm','تأكيد كلمة المرور الجديدة','new-password')+
  '<p>بعد الحفظ، سيتم تسجيل الخروج من الأجهزة الأخرى. سيظل حسابك مفتوحًا على هذا الجهاز.</p>',
  async f=>{
   validatePassword(String(f.get('password')),String(f.get('passwordConfirm')));
   await nodeApi('password',{method:'POST',body:{currentPassword:f.get('currentPassword'),password:f.get('password')}});
   toast('تم تغيير كلمة المرور وإغلاق الجلسات القديمة.');
  });
 attachPasswordReveals();
}
const renderBeforeAccountSettings=render;
render=function(){
 renderBeforeAccountSettings();
 if(!nodeUser||!previewSession)return;
 const actions=$('.header-actions');
 if(actions&&!$('#changeAccountPassword')){
  actions.insertAdjacentHTML('afterbegin','<button type="button" id="changeAccountPassword">تغيير كلمة المرور</button>');
  $('#changeAccountPassword').onclick=changeAccountPassword;
 }
};
